/**
 * One page of results with the paging numbers every list endpoint returns.
 * Mirrors the server's PageResponse; generated by fun-travels-tour-document/tools/generate-ts-dtos.py, do not edit by hand.
 */
export type PageResponseDto<T> = {
  content: T[];
  page: number;
  size: number;
  totalElements: number;
  totalPages: number;
};
